const CLOUD_NAME="efjo1aed",UPLOAD_PRESET="sweet-accessories";async function uploadImage(e){const o=new FormData;o.append("file",e),o.append("upload_preset",UPLOAD_PRESET);const a=new AbortController,r=setTimeout(()=>a.abort(),3e4),t=await fetch("https://api.cloudinary.com/v1_1/efjo1aed/image/upload",{method:"POST",body:o,signal:a.signal});clearTimeout(r);const n=await t.json();if(n.error)throw new Error(n.error.message);return n.secure_url}